cd /var/tmp/loop-bench/runs/f6d9fe281dcd/workspace/target && node -e "
import('ajv').then(({default: Ajv}) => {
  const ajv = new Ajv({allErrors: true, format: false});
  try {
    ajv.compile({type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}});
  } catch (e) {
    console.log('Caught compile error:', e.message);
  }
  const validate = ajv.compile({
    type: 'object',
    properties: {
      location: {type: 'string'},
      units: {type: 'string', enum: ['celsius', 'fahrenheit']},
      nested: {type: 'object', properties: {count: {type: 'number'}}, required: ['count']}
    },
    required: ['location']
  });
  console.log('empty:', validate({}), validate.errors);
  console.log('wrong type:', validate({location: 12345}), validate.errors);
  console.log('wrong enum:', validate({location: 'Paris', units: 'kelvin'}), validate.errors);
  console.log('nested missing:', validate({location: 'Paris', nested: {}}), validate.errors);
  console.log('nested wrong type:', validate({location: 'Paris', nested: {count: 'bad'}}), validate.errors);
});
"
